import{_ as e,o as d,c as a,l as o,t as r,N as n}from"./chunks/framework.CMqbtke2.js";const y=JSON.parse('{"title":"date | x-cmd man (man1) | print or set the system date and time","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | date - print or set the system date and time","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"date | x-cmd man (man1) | print or set the system date and time"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | date - print or set the system date and time"}]]},"headers":[],"params":{"isMan":true,"man":"date","category":"man1","desc":"print or set the system date and time"},"relativePath":"man1/date.md","filePath":"man1/date.md"}'),s={name:"man1/date.md"},i={class:"visually-hidden"},l=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>date - print or set the system date and time</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>date</strong> [<em>OPTION</em>]... [<em>+FORMAT</em>] <br> <strong>date</strong> [<em>-u|--utc|--universal</em>] [<em>MMDDhhmm</em>[[<em>CC</em>]<em>YY</em>][<em>.ss</em>]]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Display date and time in the given FORMAT. With <strong>-s</strong>, or with [MMDDhhmm[[CC]YY][.ss]], set the date and time.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-d</strong>, <strong>--date</strong>=<em>STRING</em></dt><dd>display time described by STRING, not &#39;now&#39;</dd><dt><strong>--debug</strong></dt><dd>annotate the parsed date, and warn about questionable usage to stderr</dd><dt><strong>-f</strong>, <strong>--file</strong>=<em>DATEFILE</em></dt><dd>like <strong>--date</strong>; once for each line of DATEFILE</dd><dt><strong>-I[FMT]</strong>, <strong>--iso-8601</strong>[=<em>FMT</em>]</dt><dd>output date/time in ISO 8601 format. FMT=&#39;date&#39; for date only (the default), &#39;hours&#39;, &#39;minutes&#39;, &#39;seconds&#39;, or &#39;ns&#39; for date and time to the indicated precision. Example: 2006-08-14T02:34:56-06:00</dd><dt><strong>--resolution</strong></dt><dd>output the available resolution of timestamps Example: 0.000000001</dd><dt><strong>-R</strong>, <strong>--rfc-email</strong></dt><dd>output date and time in RFC 5322 format. Example: Mon, 14 Aug 2006 02:34:56 <strong>-0600</strong></dd><dt><strong>--rfc-3339</strong>=<em>FMT</em></dt><dd>output date/time in RFC 3339 format. FMT=&#39;date&#39;, &#39;seconds&#39;, or &#39;ns&#39; for date and time to the indicated precision. Example: 2006-08-14 02:34:56-06:00</dd><dt><strong>-r</strong>, <strong>--reference</strong>=<em>FILE</em></dt><dd>display the last modification time of FILE</dd><dt><strong>-s</strong>, <strong>--set</strong>=<em>STRING</em></dt><dd>set time described by STRING</dd><dt><strong>-u</strong>, <strong>--utc</strong>, <strong>--universal</strong></dt><dd>print or set Coordinated Universal Time (UTC)</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>All options that specify the date to display are mutually exclusive. I.e.: <strong>--date</strong>, <strong>--file</strong>, <strong>--reference</strong>, <strong>--resolution</strong>.</p><p>FORMAT controls the output. Interpreted sequences are:</p><dl><dt>%%</dt><dd>a literal %</dd><dt>%a</dt><dd>locale&#39;s abbreviated weekday name (e.g., Sun)</dd><dt>%A</dt><dd>locale&#39;s full weekday name (e.g., Sunday)</dd><dt>%b</dt><dd>locale&#39;s abbreviated month name (e.g., Jan)</dd><dt>%B</dt><dd>locale&#39;s full month name (e.g., January)</dd><dt>%c</dt><dd>locale&#39;s date and time (e.g., Thu Mar 3 23:05:25 2005)</dd><dt>%C</dt><dd>century; like %Y, except omit last two digits (e.g., 20)</dd><dt>%d</dt><dd>day of month (e.g., 01)</dd><dt>%D</dt><dd>date; same as %m/%d/%y</dd><dt>%e</dt><dd>day of month, space padded; same as %_d</dd><dt>%F</dt><dd>full date; like %+4Y-%m-%d</dd><dt>%g</dt><dd>last two digits of year of ISO week number (see %G)</dd><dt>%G</dt><dd>year of ISO week number (see %V); normally useful only with %V</dd><dt>%h</dt><dd>same as %b</dd><dt>%H</dt><dd>hour (00..23)</dd><dt>%I</dt><dd>hour (01..12)</dd><dt>%j</dt><dd>day of year (001..366)</dd><dt>%k</dt><dd>hour, space padded ( 0..23); same as %_H</dd><dt>%l</dt><dd>hour, space padded ( 1..12); same as %_I</dd><dt>%m</dt><dd>month (01..12)</dd><dt>%M</dt><dd>minute (00..59)</dd><dt>%n</dt><dd>a newline</dd><dt>%N</dt><dd>nanoseconds (000000000..999999999)</dd><dt>%p</dt><dd>locale&#39;s equivalent of either AM or PM; blank if not known</dd><dt>%P</dt><dd>like %p, but lower case</dd><dt>%q</dt><dd>quarter of year (1..4)</dd><dt>%r</dt><dd>locale&#39;s 12-hour clock time (e.g., 11:11:04 PM)</dd><dt>%R</dt><dd>24-hour hour and minute; same as %H:%M</dd><dt>%s</dt><dd>seconds since the Epoch (1970-01-01 00:00 UTC)</dd><dt>%S</dt><dd>second (00..60)</dd><dt>%t</dt><dd>a tab</dd><dt>%T</dt><dd>time; same as %H:%M:%S</dd><dt>%u</dt><dd>day of week (1..7); 1 is Monday</dd><dt>%U</dt><dd>week number of year, with Sunday as first day of week (00..53)</dd><dt>%V</dt><dd>ISO week number, with Monday as first day of week (01..53)</dd><dt>%w</dt><dd>day of week (0..6); 0 is Sunday</dd><dt>%W</dt><dd>week number of year, with Monday as first day of week (00..53)</dd><dt>%x</dt><dd>locale&#39;s date representation (e.g., 12/31/99)</dd><dt>%X</dt><dd>locale&#39;s time representation (e.g., 23:13:48)</dd><dt>%y</dt><dd>last two digits of year (00..99)</dd><dt>%Y</dt><dd>year</dd><dt>%z</dt><dd>+hhmm numeric time zone (e.g., <strong>-0400</strong>)</dd><dt>%😒</dt><dd>+hh:mm numeric time zone (e.g., <strong>-04</strong>:00)</dd><dt>%:😒</dt><dd>+hh:mm:ss numeric time zone (e.g., <strong>-04</strong>:00:00)</dd><dt>%::😒</dt><dd>numeric time zone with : to necessary precision (e.g., <strong>-04</strong>, +05:30)</dd><dt>%Z</dt><dd>alphabetic time zone abbreviation (e.g., EDT)</dd></dl><p>By default, date pads numeric fields with zeroes. The following optional flags may follow &#39;%&#39;:</p><dl><dt>-</dt><dd>(hyphen) do not pad the field</dd><dt>_</dt><dd>(underscore) pad with spaces</dd><dt>0</dt><dd>(zero) pad with zeros</dd><dt>+</dt><dd>pad with zeros, and put &#39;+&#39; before future years with &gt;4 digits</dd><dt>^</dt><dd>use upper case if possible</dd><dt>#</dt><dd>use opposite case if possible</dd></dl><p>After any flags comes an optional field width, as a decimal number; then an optional modifier, which is either E to use the locale&#39;s alternate representations if available, or O to use the locale&#39;s alternate numeric symbols if available.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Convert seconds since the Epoch (1970-01-01 UTC) to a date</p><blockquote><p><code>$ date --date=&#39;@2147483647&#39;</code></p></blockquote><p>Show the time on the west coast of the US (use <strong>tzselect</strong>(1) to find TZ)</p><blockquote><p><code>$ TZ=&#39;America/Los_Angeles&#39; date</code></p></blockquote><p>Show the local time for 9AM next Friday on the west coast of the US</p><blockquote><p><code>$ date --date=&#39;TZ=&quot;America/Los_Angeles&quot; 09:00 next Fri&#39;</code></p></blockquote><h2 id="date-string" tabindex="-1">DATE STRING <a class="header-anchor" href="#date-string" aria-label="Permalink to &quot;DATE STRING&quot;">​</a></h2><p>The --date=STRING is a mostly free format human readable date string such as &quot;Sun, 29 Feb 2004 16:21:42 -0800&quot; or &quot;2004-02-29 16:21:42&quot; or even &quot;next Thursday&quot;. A date string may contain items indicating calendar date, time of day, time zone, day of week, relative time, relative date, and numbers. An empty string indicates the beginning of the day. The date string format is more complex than is easily documented here but is fully described in the info documentation.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/date%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/date\\</a>&gt; <br> or available locally via: info &#39;(coreutils) date invocation&#39;</p>',31);function m(t,h,c,u,g,p){return d(),a("div",null,[o("h1",i,r(t.$params.man),1),l])}const b=e(s,[["render",m]]);export{y as __pageData,b as default};
